<section class="card narrow"><h1><?= $e($title) ?></h1><form method="post" action="<?= $purpose==='register'?'/register':'/forgot-password' ?>" data-email-form><input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="purpose" value="<?= $e($purpose) ?>"><label>邮箱<input type="email" name="email" required autocomplete="email" maxlength="191"></label><button type="button" class="secondary" data-send-code>发送验证码</button><p data-code-message role="status"></p><label>邮箱验证码<input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required autocomplete="one-time-code"></label><?php if($purpose==='register'): ?><label>昵称<input name="name" required maxlength="80" autocomplete="nickname"></label><?php endif ?><label>新密码<input name="password" type="password" minlength="12" maxlength="72" autocomplete="new-password" required></label><p class="muted">12～72 字节，包含大写字母、小写字母和数字。</p><button type="submit"><?= $e($title) ?></button></form><p class="muted">提交前请阅读 <a href="/privacy">账号与隐私说明</a>。</p><a href="/login">返回登录</a></section>